    expect(r.ease).toBeCloseTo(2.7 - 0.32);
  });

  it("keep is idempotent per noun and errorType", () => {
    const a = fresh();
    const b = fresh();
    expect(b).toEqual(a);
    expect(all()).toHaveLength(1);
