    const b = runBackup();
    const c = runRestore();
    await flush();
    expect(db.state.log).toEqual(["select:items"]);
    release();
    await Promise.all([first, a, b, c]);
    await flush();
    expect(db.state.log).toEqual(["select:items", "select:items", "upsert:items"]);
    expect(db.state.maxInFlight).toBe(1);
    await runBackup();
