  });
});

describe("runRestore", () => {
  it("fetches a second page when the first has 1000 rows", async () => {
    db.state.remote = Array.from({ length: 1200 }, (_, i) => remoteRow(i + 1));
    await expect(runRestore()).resolves.toBe(true);
